SELECT map_id, door_id, door_name, device_id, pos_x, pos_y
FROM tb_graphic_map_door WHERE map_id = #{mapId}
ORDER BY door_name, door_id

SELECT d.map_id, d.door_id, d.door_name, d.device_id, d.pos_x, d.pos_y
FROM tb_graphic_map_door d JOIN tb_graphic_map m ON m.map_id = d.map_id AND m.del_yn = 'N'
WHERE d.map_id = #{mapId} AND d.door_id = #{doorId}
